    <div class="top">
      <div>
        <div class="brand">ps5-vibe · admin remote</div>
        <h1>Controller Admin Panel</h1>
        <p class="sub">Full remote control over DualSense vibration parameters and patterns.</p>
      </div>
      <button class="ghost" id="home">Home</button>
    </div>

